SELECT pe.payment_id, pe.business_date, pe.amount FROM payment_event pe JOIN payment_type_catalog t ON t.payment_type = pe.payment_type WHERE t.name_zh = '现金支取' AND pe.amount > 5000000 ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT party_id, annual_income FROM person_profile WHERE annual_income > 1000000 ORDER BY annual_income DESC, party_id;	bankreg_main
SELECT p.party_id, p.display_name, op.operating_status FROM party p JOIN organization_profile op ON op.party_id = p.party_id WHERE op.registered_region IN (SELECT region_code FROM organization_unit WHERE unit_name = '上海分行') ORDER BY p.party_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS loan_count FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY loan_count DESC, i.institution_name;	bankreg_main
SELECT ou.org_unit_id, ou.unit_name, COUNT(*) AS account_count FROM account a JOIN organization_unit ou ON ou.org_unit_id = a.org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY account_count DESC, ou.org_unit_id;	bankreg_main
SELECT s.sector_name_zh, ROUND(SUM(a.contract_amount), 2) AS total_contract FROM credit_agreement a JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY s.sector_code, s.sector_name_zh ORDER BY total_contract DESC, s.sector_name_zh;	bankreg_main
SELECT i.institution_name, cs.net_capital, cs.risk_weighted_assets FROM capital_snapshot cs JOIN institution i ON i.institution_id = cs.institution_id ORDER BY cs.net_capital DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, ROUND(SUM(abs.ledger_balance), 2) AS total_deposit FROM account_balance_snapshot abs JOIN account a ON a.account_id = abs.account_id JOIN institution i ON i.institution_id = a.institution_id WHERE a.account_kind = 'SAVINGS' GROUP BY i.institution_id, i.institution_name ORDER BY total_deposit DESC, i.institution_name;	bankreg_main
SELECT p.party_id, p.display_name, ROUND(SUM(a.contract_amount), 2) AS total_contract FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE EXISTS (     SELECT 1 FROM party_relation pr     JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type     WHERE pr.source_party_id = p.party_id       AND rt.relation_name_zh <> '非关联方' ) GROUP BY p.party_id, p.display_name HAVING SUM(a.contract_amount) > 300000000 ORDER BY total_contract DESC, p.party_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS record_count,        ROUND(SUM(r.observed_value), 4) AS total_observed FROM data_security_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.exception_flag = 1 GROUP BY i.institution_id, i.institution_name ORDER BY total_observed DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(*) AS overdue_records FROM regulatory_submission_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_id, i.institution_name HAVING COUNT(*) >= 20 ORDER BY overdue_records DESC, i.institution_name;	bankreg_main
SELECT d.loan_id, d.principal_overdue_days, g.grade_name_zh, rc.as_of_date FROM delinquency_snapshot d JOIN risk_classification rc ON rc.loan_id = d.loan_id JOIN classification_grade g ON g.grade_code = rc.grade_code WHERE d.principal_overdue_days > 90   AND g.is_nonperforming = 0 ORDER BY d.principal_overdue_days DESC, d.loan_id;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN s.risk_category IN ('RESTRICTED','EXIT')                       THEN pi.instruction_amount ELSE 0 END), 2) AS restricted_amount,        ROUND(SUM(pi.instruction_amount), 2) AS total_amount,        ROUND(SUM(CASE WHEN s.risk_category IN ('RESTRICTED','EXIT')                       THEN pi.instruction_amount ELSE 0 END) * 1.0              / SUM(pi.instruction_amount), 6) AS restricted_ratio FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id LEFT JOIN organization_profile op ON op.party_id = pi.intended_payee_party_id LEFT JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY i.institution_id, i.institution_name ORDER BY restricted_ratio DESC, i.institution_name;	bankreg_main
SELECT p.party_id, p.display_name, g.guarantee_count, b.agreement_count FROM party p JOIN (SELECT guarantor_party_id AS pid, COUNT(*) AS guarantee_count       FROM guarantor_commitment GROUP BY guarantor_party_id) g ON g.pid = p.party_id JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count       FROM credit_agreement GROUP BY borrower_party_id) b ON b.pid = p.party_id ORDER BY g.guarantee_count DESC, p.party_id;	bankreg_main
SELECT pe.payment_id, pe.business_date, t.name_zh, pe.amount, ou.unit_name FROM payment_event pe JOIN payment_type_catalog t ON t.payment_type = pe.payment_type JOIN organization_unit ou ON ou.org_unit_id = pe.origin_org_unit_id WHERE pe.is_cash = 1 AND pe.amount > 5000000 AND pe.status = 'SETTLED' ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT a.agreement_id, p.display_name, s1.sector_name_zh AS borrower_sector,        s2.sector_name_zh AS target_sector, a.contract_amount FROM credit_agreement a JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s1 ON s1.sector_code = op.industry_code JOIN industry_sector s2 ON s2.sector_code = a.target_industry_code JOIN party p ON p.party_id = a.borrower_party_id WHERE a.target_industry_code <> op.industry_code ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT pe.payment_id, pe.business_date, pe.amount,        ah1.party_id AS payer_party_id, ah2.party_id AS payee_party_id FROM payment_event pe JOIN account_holder ah1 ON ah1.account_id = pe.from_account_id AND ah1.holder_role = 'PRIMARY' JOIN account_holder ah2 ON ah2.account_id = pe.to_account_id AND ah2.holder_role = 'PRIMARY' JOIN party_relation pr ON pr.source_party_id = ah1.party_id AND pr.target_party_id = ah2.party_id WHERE pe.status = 'SETTLED' AND pr.relation_type <> 'NON_RELATED' ORDER BY pe.amount DESC, pe.payment_id;	bankreg_main
SELECT a.agreement_id, p.display_name, COUNT(*) AS loan_count FROM credit_agreement a JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN party p ON p.party_id = a.borrower_party_id GROUP BY a.agreement_id, p.display_name HAVING COUNT(*) >= 3 ORDER BY loan_count DESC, a.agreement_id;	bankreg_main
SELECT r.record_id, i.institution_name, r.event_date, r.deadline_date,        CAST(julianday('2026-06-30') - julianday(r.deadline_date) AS INTEGER) AS overdue_days FROM customer_due_diligence_event_v3 r JOIN institution i ON i.institution_id = r.institution_id WHERE r.completion_date IS NULL ORDER BY overdue_days DESC, r.record_id LIMIT 20;	bankreg_main
WITH ranked AS (     SELECT i.institution_name, lbs.loan_id, lbs.principal_balance,            ROW_NUMBER() OVER (PARTITION BY i.institution_id                               ORDER BY lbs.principal_balance DESC, lbs.loan_id) AS rn     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN institution i ON i.institution_id = a.institution_id ) SELECT institution_name, loan_id, principal_balance, rn FROM ranked WHERE rn = 1 ORDER BY institution_name;	bankreg_main
SELECT sa.security_id, sa.secured_amount,        (SELECT COUNT(*) FROM guarantor_commitment gc WHERE gc.security_id = sa.security_id) AS guarantor_count FROM security_agreement sa WHERE NOT EXISTS (SELECT 1 FROM collateral_link cl WHERE cl.security_id = sa.security_id)   AND EXISTS (SELECT 1 FROM guarantor_commitment gc WHERE gc.security_id = sa.security_id) ORDER BY sa.secured_amount DESC, sa.security_id;	bankreg_main
SELECT CASE          WHEN d.principal_overdue_days IS NULL THEN '未逾期'          WHEN d.principal_overdue_days <= 30 THEN '1-30天'          WHEN d.principal_overdue_days <= 90 THEN '31-90天'          WHEN d.principal_overdue_days <= 180 THEN '91-180天'          WHEN d.principal_overdue_days <= 360 THEN '181-360天'          ELSE '360天以上' END AS bucket,        COUNT(*) AS loan_count FROM loan_drawdown ld LEFT JOIN delinquency_snapshot d ON d.loan_id = ld.loan_id GROUP BY bucket ORDER BY CASE bucket          WHEN '未逾期' THEN 0 WHEN '1-30天' THEN 1 WHEN '31-90天' THEN 2          WHEN '91-180天' THEN 3 WHEN '181-360天' THEN 4 ELSE 5 END;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(*) AS loan_count,        ROUND(SUM(lbs.principal_balance), 2) AS total_balance,        ROUND(AVG(lbs.principal_balance), 2) AS avg_balance FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id WHERE p.party_type = 'CORPORATE' GROUP BY p.party_id, p.display_name ORDER BY avg_balance DESC, p.party_id LIMIT 5;	bankreg_main
SELECT ou.unit_name, COUNT(DISTINCT sm.staff_id) AS staff_count,        COUNT(*) AS txn_count FROM payment_event pe JOIN service_operator so ON so.operator_id = pe.operator_id JOIN staff_member sm ON sm.staff_id = so.staff_id JOIN organization_unit ou ON ou.org_unit_id = sm.home_org_unit_id WHERE pe.is_cash = 1 GROUP BY ou.org_unit_id, ou.unit_name ORDER BY txn_count DESC, ou.unit_name LIMIT 10;	bankreg_main
SELECT p.party_id, p.display_name, c.card_count, td.deposit_count FROM party p JOIN (SELECT holder_party_id AS pid, COUNT(*) AS card_count       FROM payment_card       WHERE card_type = 'CREDIT'       GROUP BY holder_party_id) c ON c.pid = p.party_id JOIN (SELECT ah.party_id AS pid, COUNT(DISTINCT t.account_id) AS deposit_count       FROM term_deposit t       JOIN account_holder ah ON ah.account_id = t.account_id       GROUP BY ah.party_id) td ON td.pid = p.party_id ORDER BY td.deposit_count DESC, p.party_id;	bankreg_main
SELECT i.institution_name,        ROUND(AVG(julianday('2026-06-30') - julianday(ld.disbursed_on)), 2) AS avg_age_days FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY avg_age_days DESC, i.institution_name;	bankreg_main
WITH sector_balance AS (     SELECT s.sector_name_zh, SUM(lbs.principal_balance) AS total_balance     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN organization_profile op ON op.party_id = a.borrower_party_id     JOIN industry_sector s ON s.sector_code = op.industry_code     GROUP BY s.sector_code, s.sector_name_zh ), cumulative AS (     SELECT sector_name_zh, total_balance,            SUM(total_balance) OVER (ORDER BY total_balance DESC, sector_name_zh                                    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)            * 1.0 / SUM(total_balance) OVER () AS cum_share     FROM sector_balance ) SELECT sector_name_zh, ROUND(total_balance, 2) AS total_balance,        ROUND(cum_share, 6) AS cumulative_share FROM cumulative WHERE cum_share <= 0.8 ORDER BY cumulative_share;	bankreg_main
SELECT p.party_id, p.display_name, i.institution_name, COUNT(*) AS active_loans FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id WHERE ld.status = 'ACTIVE' GROUP BY p.party_id, p.display_name, i.institution_id, i.institution_name HAVING COUNT(*) >= 2 ORDER BY active_loans DESC, p.party_id;	bankreg_main
SELECT sa.security_id, sa.secured_amount, cl.collateral_id, cv.valuation_amount FROM security_agreement sa JOIN collateral_link cl ON cl.security_id = sa.security_id JOIN collateral_valuation cv ON cv.collateral_id = cl.collateral_id WHERE cv.valued_on = (SELECT MAX(cv2.valued_on) FROM collateral_valuation cv2                       WHERE cv2.collateral_id = cl.collateral_id)   AND cv.valuation_amount > sa.secured_amount * 2 ORDER BY cv.valuation_amount - sa.secured_amount DESC, sa.security_id;	bankreg_main
SELECT pe.from_account_id AS account_id, pe.business_date, COUNT(*) AS txn_count FROM payment_event pe WHERE pe.from_account_id IS NOT NULL GROUP BY pe.from_account_id, pe.business_date HAVING COUNT(*) >= 3 ORDER BY txn_count DESC, account_id, pe.business_date LIMIT 20;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cnt FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE julianday('2026-06-30') - julianday(lbs.overdue_since) >= 90 GROUP BY i.institution_id, i.institution_name ORDER BY cnt DESC, i.institution_name;	bankreg_main
SELECT a.agreement_id, p.display_name, a.contract_amount FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id WHERE p.party_type = 'CORPORATE' AND p.status = 'FROZEN' AND a.status = 'ACTIVE' ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT i.institution_name, ld.loan_id,        ROUND(lbs.principal_balance,2) AS bal,        ROUND((SELECT AVG(x.principal_balance) FROM loan_balance_snapshot x JOIN loan_drawdown d2 ON d2.loan_id=x.loan_id JOIN credit_agreement a2 ON a2.agreement_id=d2.agreement_id WHERE a2.institution_id=a.institution_id),2) AS inst_avg,        ROUND(lbs.principal_balance - (SELECT AVG(x.principal_balance) FROM loan_balance_snapshot x JOIN loan_drawdown d2 ON d2.loan_id=x.loan_id JOIN credit_agreement a2 ON a2.agreement_id=d2.agreement_id WHERE a2.institution_id=a.institution_id),2) AS gap FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id=lbs.loan_id JOIN credit_agreement a ON a.agreement_id=ld.agreement_id JOIN institution i ON i.institution_id=a.institution_id WHERE lbs.principal_balance > 2*(SELECT AVG(x.principal_balance) FROM loan_balance_snapshot x JOIN loan_drawdown d2 ON d2.loan_id=x.loan_id JOIN credit_agreement a2 ON a2.agreement_id=d2.agreement_id WHERE a2.institution_id=a.institution_id) ORDER BY gap DESC, ld.loan_id;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(CASE WHEN NOT EXISTS (            SELECT 1 FROM party_relation pr            WHERE pr.source_party_id = a.borrower_party_id AND pr.relation_type <> 'NON_RELATED'        ) THEN a.contract_amount ELSE 0 END), 2) AS nonrel_amt,        ROUND(SUM(a.contract_amount), 2) AS total_amt,        ROUND(SUM(CASE WHEN NOT EXISTS (            SELECT 1 FROM party_relation pr            WHERE pr.source_party_id = a.borrower_party_id AND pr.relation_type <> 'NON_RELATED'        ) THEN a.contract_amount ELSE 0 END) * 1.0 / SUM(a.contract_amount), 6) AS ratio FROM credit_agreement a JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY ratio DESC, i.institution_name;	bankreg_main
WITH bal AS (     SELECT i.institution_id, i.institution_name, p.party_id, p.display_name,            SUM(lbs.principal_balance) AS b, cs.net_capital     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN party p ON p.party_id = a.borrower_party_id     JOIN institution i ON i.institution_id = a.institution_id     JOIN capital_snapshot cs ON cs.institution_id = i.institution_id     WHERE p.party_type = 'CORPORATE'     GROUP BY i.institution_id, i.institution_name, p.party_id, p.display_name, cs.net_capital ) SELECT institution_name, COUNT(*) AS cnt FROM bal WHERE b * 1.0 / net_capital > 0.10 GROUP BY institution_id, institution_name ORDER BY cnt DESC, institution_name;	bankreg_main
SELECT eg.exposure_group_id, eg.group_name,        ROUND(SUM(lbs.principal_balance), 2) AS bal,        cs.net_capital,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS ratio FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN capital_snapshot cs ON cs.institution_id = eg.institution_id WHERE eg.group_type = 'GROUP_CUSTOMER' GROUP BY eg.exposure_group_id, eg.group_name, cs.net_capital HAVING SUM(lbs.principal_balance) * 1.0 / cs.net_capital > 0.10 ORDER BY ratio DESC, eg.exposure_group_id;	bankreg_main
SELECT a.agreement_id, a.maturity_on, ldp.loan_id, ldp.status,        ROUND(a.contract_amount,2) AS contract_amount FROM credit_agreement a JOIN loan_drawdown ldp ON ldp.agreement_id=a.agreement_id WHERE a.status='MATURED' AND ldp.status='ACTIVE' ORDER BY ldp.loan_id;	bankreg_main
SELECT ld.loan_id, ld.disbursement_account_id, ld.disbursed_on, pe.payment_id,        pe.business_date, ROUND(pe.amount,2) AS transferred,        CAST(julianday(pe.business_date)-julianday(ld.disbursed_on) AS INTEGER) AS days_lapse FROM loan_drawdown ld JOIN payment_event pe ON pe.from_account_id=ld.disbursement_account_id WHERE pe.payment_type='TRANSFER' AND pe.status='SETTLED'   AND julianday(pe.business_date)-julianday(ld.disbursed_on) BETWEEN 0 AND 7 ORDER BY days_lapse, transferred DESC, ld.loan_id;	bankreg_main
WITH co AS (     SELECT i.institution_id, i.institution_name, p.party_id, p.display_name,            SUM(lbs.principal_balance) * 1.0 / cs.net_capital AS ratio     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN party p ON p.party_id = a.borrower_party_id     JOIN institution i ON i.institution_id = a.institution_id     JOIN capital_snapshot cs ON cs.institution_id = i.institution_id     WHERE p.party_type = 'CORPORATE'     GROUP BY i.institution_id, i.institution_name, p.party_id, p.display_name, cs.net_capital ), rk AS (     SELECT institution_name, display_name, ratio,            ROW_NUMBER() OVER (PARTITION BY institution_id ORDER BY ratio DESC) AS rn     FROM co ) SELECT institution_name, display_name, ROUND(ratio, 6) AS ratio FROM rk WHERE rn = 1 ORDER BY institution_name;	bankreg_main
SELECT loan_id, principal_balance, quartile FROM (     SELECT lbs.loan_id, ROUND(lbs.principal_balance,2) AS principal_balance,            NTILE(4) OVER (PARTITION BY a.institution_id ORDER BY lbs.principal_balance DESC) AS quartile     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id=lbs.loan_id     JOIN credit_agreement a ON a.agreement_id=ld.agreement_id ) ORDER BY quartile ASC, principal_balance DESC LIMIT 300;	bankreg_main
SELECT ah.party_id AS party_id FROM account_holder ah JOIN term_deposit td ON td.account_id=ah.account_id INTERSECT SELECT a.borrower_party_id AS party_id FROM credit_agreement a ORDER BY party_id;	bankreg_main
SELECT party_id FROM (     SELECT sm.person_party_id AS party_id     FROM staff_member sm     WHERE sm.employment_status = 'ACTIVE'     EXCEPT     SELECT ah.party_id AS party_id     FROM account_holder ah ) ORDER BY party_id;	bankreg_main
SELECT a.account_id FROM account a WHERE a.account_kind='SAVINGS'   AND NOT EXISTS (SELECT 1 FROM payment_event e WHERE e.from_account_id=a.account_id AND e.is_cash=1) ORDER BY a.account_id LIMIT 300;	bankreg_main
SELECT c.collateral_type, ROUND(AVG(v.valuation_amount), 2) AS avg_val, COUNT(*) AS cnt FROM collateral_valuation v JOIN collateral_asset c ON c.collateral_id = v.collateral_id WHERE v.appraiser_kind = 'BANK_INTERNAL' GROUP BY c.collateral_type ORDER BY avg_val DESC;	bankreg_main
WITH ds AS (   SELECT d.agreement_id, SUM(d.disbursed_amount) AS total_disbursed, COUNT(DISTINCT d.loan_id) AS drawdown_cnt   FROM loan_drawdown d GROUP BY d.agreement_id ) SELECT a.agreement_id, ROUND(a.contract_amount,2) AS contract_amount,        ROUND(ds.total_disbursed,2) AS total_disbursed,        ROUND(ds.total_disbursed - a.contract_amount,2) AS excess_amount,        ds.drawdown_cnt FROM ds JOIN credit_agreement a ON a.agreement_id=ds.agreement_id WHERE ds.total_disbursed > a.contract_amount ORDER BY a.agreement_id;	bankreg_main
SELECT a.borrower_party_id, p.display_name,        COUNT(DISTINCT CASE WHEN rs.status='OVERDUE' THEN ld.loan_id END) AS overdue_loans,        COUNT(DISTINCT ld.loan_id) AS total_loans FROM credit_agreement a JOIN party p ON p.party_id=a.borrower_party_id JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id JOIN repayment_schedule rs ON rs.loan_id=ld.loan_id GROUP BY a.borrower_party_id, p.display_name HAVING COUNT(DISTINCT CASE WHEN rs.status='OVERDUE' THEN ld.loan_id END) >= 1    AND COUNT(DISTINCT CASE WHEN rs.status='OVERDUE' THEN ld.loan_id END) < COUNT(DISTINCT ld.loan_id) ORDER BY overdue_loans DESC, a.borrower_party_id;	bankreg_main
SELECT pi.instruction_id, ld.loan_id, p1.display_name AS borrower, p2.display_name AS payee,        ROUND(pi.instruction_amount,2) AS amount FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id=pi.loan_id JOIN credit_agreement a ON a.agreement_id=ld.agreement_id JOIN party p1 ON p1.party_id=a.borrower_party_id JOIN party p2 ON p2.party_id=pi.intended_payee_party_id WHERE pi.intended_payee_party_id <> a.borrower_party_id AND pi.status='EXECUTED' ORDER BY amount DESC, pi.instruction_id;	bankreg_main
SELECT rs.loan_id, COUNT(*) AS overdue_cnt,        ROUND(SUM(rs.principal_due),2) AS overdue_principal FROM repayment_schedule rs GROUP BY rs.loan_id HAVING SUM(CASE WHEN rs.status='PAID' THEN 1 ELSE 0 END) = 0 ORDER BY overdue_principal DESC, rs.loan_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, ROUND(lbs.principal_balance, 2) AS balance, ROUND(lbs.overdue_principal, 2) AS overdue_principal FROM loan_drawdown ld JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id WHERE ld.status = 'WRITTEN_OFF' AND lbs.principal_balance > 10000000 ORDER BY lbs.principal_balance DESC, ld.loan_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, ac.account_id, ac.account_kind, ROUND(ld.disbursed_amount,2) AS amount FROM loan_drawdown ld JOIN account ac ON ac.account_id=ld.disbursement_account_id WHERE ac.account_kind='SAVINGS' ORDER BY amount DESC, ld.loan_id;	bankreg_main
WITH fam_avg AS (   SELECT institution_id, product_family, AVG(annual_interest_rate) AS fam_rate   FROM credit_agreement   GROUP BY institution_id, product_family ) SELECT p.display_name AS 借款人名称, a.borrower_party_id AS 客户编号,        a.annual_interest_rate AS 合同年利率,        ROUND(fa.fam_rate, 4) AS 同类产品平均利率,        ROUND(fa.fam_rate - a.annual_interest_rate, 4) AS 利率价差 FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id JOIN fam_avg fa ON fa.institution_id = a.institution_id AND fa.product_family = a.product_family WHERE a.annual_interest_rate < fa.fam_rate   AND EXISTS (SELECT 1 FROM party_relation pr               JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type               WHERE (pr.source_party_id = a.borrower_party_id OR pr.target_party_id = a.borrower_party_id)                 AND rc.relation_name_zh <> '非关联方') ORDER BY 利率价差 DESC, a.borrower_party_id;	bankreg_main
SELECT ph.product_id, COUNT(*) AS asset_cnt FROM product_holding_snapshot ph WHERE ph.investment_path = 'NESTED_SPV' GROUP BY ph.product_id ORDER BY asset_cnt DESC, ph.product_id LIMIT 20;	bankreg_main
SELECT lb.loan_id,        lb.principal_balance,        MAX(ds.principal_overdue_days) AS max_days FROM loan_balance_snapshot lb JOIN delinquency_snapshot ds ON ds.loan_id = lb.loan_id WHERE lb.overdue_principal > 0   AND lb.principal_balance > 90000000 GROUP BY lb.loan_id, lb.principal_balance HAVING MAX(ds.principal_overdue_days) >= 200 ORDER BY max_days DESC, lb.loan_id;	bankreg_main
WITH gs AS (   SELECT gc.guarantor_party_id AS pid, SUM(gc.guaranteed_amount) AS g_total   FROM guarantor_commitment gc   GROUP BY gc.guarantor_party_id ), bs AS (   SELECT a.borrower_party_id AS pid, SUM(a.contract_amount) AS b_total   FROM credit_agreement a   GROUP BY a.borrower_party_id ) SELECT p.display_name AS 企业名称, g.pid AS 客户编号,        ROUND(g.g_total, 2) AS 对外担保合计,        ROUND(bs.b_total, 2) AS 自身借款合计,        ROUND(g.g_total - bs.b_total, 2) AS 担保负债差额 FROM gs g JOIN bs ON bs.pid = g.pid JOIN party p ON p.party_id = g.pid WHERE p.party_type = 'CORPORATE' AND g.g_total > bs.b_total ORDER BY 担保负债差额 DESC, g.pid;	bankreg_main
SELECT p.display_name, sm.staff_id, COUNT(a.agreement_id) AS cnt FROM staff_member sm JOIN party p ON p.party_id=sm.person_party_id JOIN credit_agreement a ON a.borrower_party_id=p.party_id GROUP BY p.party_id ORDER BY cnt DESC, sm.staff_id;	bankreg_main
SELECT p.display_name, p.party_id, ROUND(SUM(lbs.principal_balance),2) AS bal, pp.annual_income,        ROUND(SUM(lbs.principal_balance)*1.0/pp.annual_income,2) AS multiple FROM person_profile pp JOIN party p ON p.party_id=pp.party_id JOIN credit_agreement a ON a.borrower_party_id=p.party_id JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id=ld.loan_id GROUP BY p.party_id, pp.annual_income HAVING SUM(lbs.principal_balance)*1.0/pp.annual_income>2 ORDER BY multiple DESC, p.party_id LIMIT 200;	bankreg_main
SELECT lpc.product_name_zh AS 产品类别名称,        COUNT(rs.installment_id) AS 逾期期数,        ROUND(SUM(rs.principal_due), 2) AS 逾期本金合计 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN loan_product_catalog lpc ON lpc.product_code = ld.drawdown_type WHERE rs.status = 'OVERDUE' GROUP BY lpc.product_name_zh ORDER BY 逾期本金合计 DESC, lpc.product_name_zh;	bankreg_main
SELECT i.institution_name,        SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30')<0 THEN 1 ELSE 0 END) AS expired_cnt,        SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30') BETWEEN 0 AND 90 THEN 1 ELSE 0 END) AS soon_cnt,        SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30')>90 THEN 1 ELSE 0 END) AS far_cnt FROM term_deposit td JOIN account a ON a.account_id = td.account_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name HAVING SUM(CASE WHEN julianday(td.maturity_on)-julianday('2026-06-30')<0 THEN 1 ELSE 0 END) >= 20 ORDER BY expired_cnt DESC, i.institution_name;	bankreg_main
WITH multi AS (   SELECT account_id FROM account_holder GROUP BY account_id HAVING COUNT(*) > 1 ) SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT m.account_id) AS 联合账户数量 FROM multi m JOIN account a ON a.account_id = m.account_id JOIN organization_unit ou ON ou.org_unit_id = a.org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 联合账户数量 DESC, ou.org_unit_id;	bankreg_main
SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT ld.loan_id) AS 逾期笔数,        ROUND(SUM(lbs.overdue_principal), 2) AS 逾期本金合计 FROM credit_agreement a JOIN organization_unit ou ON ou.org_unit_id = a.managing_org_unit_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id WHERE lbs.overdue_principal > 0 GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 逾期本金合计 DESC, ou.org_unit_id;	bankreg_main
SELECT i.institution_name, COUNT(rs.installment_id) AS 逾期期数, ROUND(SUM(rs.interest_due), 2) AS 利息合计 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = ca.institution_id WHERE rs.status = 'OVERDUE' GROUP BY i.institution_id, i.institution_name HAVING COUNT(rs.installment_id) >= 30 ORDER BY 逾期期数 DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT rs.loan_id) AS 逾期贷款数 FROM repayment_schedule rs JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = ca.institution_id WHERE rs.status = 'OVERDUE' GROUP BY i.institution_id, i.institution_name HAVING COUNT(DISTINCT rs.loan_id) >= 240 ORDER BY 逾期贷款数 DESC, i.institution_name;	bankreg_main
SELECT rs.loan_id, rs.installment_no, rs.principal_due, rs.interest_due FROM repayment_schedule rs WHERE rs.status = 'OVERDUE' AND rs.principal_due > 90000000 ORDER BY rs.principal_due DESC, rs.loan_id;	bankreg_main
WITH fac AS (SELECT cf.institution_id, SUM(cf.limit_amount) AS tl, COUNT(cf.facility_id) AS n FROM credit_facility cf GROUP BY cf.institution_id), drawn AS (SELECT a.institution_id, SUM(ld.disbursed_amount) AS td FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id=ld.agreement_id GROUP BY a.institution_id), cap AS (SELECT cs.institution_id, cs.net_capital AS nc FROM capital_snapshot cs) SELECT i.institution_name, ROUND(f.tl,2) AS tl, ROUND(d.td,2) AS td, ROUND(c.nc,2) AS nc,        ROUND(d.td*1.0/c.nc,4) AS ratio FROM fac f JOIN drawn d ON d.institution_id=f.institution_id JOIN cap c ON c.institution_id=f.institution_id JOIN institution i ON i.institution_id=f.institution_id WHERE d.td > c.nc ORDER BY ratio DESC, i.institution_name;	bankreg_main
SELECT sa.security_id AS 担保合同编号,        ROUND(sa.secured_amount, 2) AS 设定担保金额,        COUNT(DISTINCT gc.commitment_id) AS 保证人个数,        ROUND(SUM(gc.guaranteed_amount), 2) AS 保证金额合计 FROM security_agreement sa JOIN guarantor_commitment gc ON gc.security_id = sa.security_id WHERE gc.status = 'ACTIVE' AND sa.security_type = 'GUARANTEE' GROUP BY sa.security_id, sa.secured_amount HAVING SUM(gc.guaranteed_amount) < sa.secured_amount ORDER BY 保证金额合计 DESC, sa.security_id;	bankreg_main
SELECT cf.facility_id, cf.limit_amount, sc.name_zh AS 额度状态名称 FROM credit_facility cf JOIN status_catalog sc ON sc.status_code = cf.status AND sc.entity = 'credit_agreement' WHERE cf.facility_type = 'REVOLVING' ORDER BY cf.limit_amount DESC, cf.facility_id;	bankreg_main
SELECT i.institution_name, cf.facility_type, ROUND(SUM(cf.limit_amount), 2) AS 授信限额合计 FROM credit_facility cf JOIN institution i ON i.institution_id = cf.institution_id GROUP BY i.institution_id, i.institution_name, cf.facility_type HAVING SUM(cf.limit_amount) > 2000000000 ORDER BY 授信限额合计 DESC, i.institution_name;	bankreg_main
WITH wp AS (   SELECT product_id, minimum_holding_days,          NTILE(4) OVER (ORDER BY actual_raise_amount DESC) AS quartile   FROM wealth_product WHERE status = 'ON_SALE' ) SELECT q.quartile,        COUNT(*) AS cnt FROM wp q WHERE q.minimum_holding_days > 0 GROUP BY q.quartile HAVING COUNT(*) BETWEEN 31 AND 33 ORDER BY q.quartile;	bankreg_main
SELECT ROUND(SUM(cf.limit_amount), 2) AS 循环授信限额合计, COUNT(DISTINCT ld.loan_id) AS 发放笔数 FROM credit_facility cf JOIN credit_agreement ca ON ca.facility_id = cf.facility_id JOIN loan_drawdown ld ON ld.agreement_id = ca.agreement_id JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode WHERE cf.facility_type = 'REVOLVING' AND pm.payment_mode_name_zh = '受托支付' ORDER BY 循环授信限额合计 DESC;	bankreg_main
SELECT it.name_zh AS 融资工具中文名称, sc.name_zh AS 实体状态中文名称 FROM instrument_type_catalog it CROSS JOIN status_catalog sc WHERE sc.entity = 'loan_drawdown' ORDER BY it.name_zh, sc.name_zh;	bankreg_main
SELECT ou.org_unit_id AS 营业单元编号, ou.unit_name AS 营业单元名称,        COUNT(DISTINCT sa.staff_id) AS 信贷客户经理人数 FROM staff_assignment sa JOIN organization_unit ou ON ou.org_unit_id = sa.org_unit_id WHERE sa.role_code = 'CREDIT_OFFICER' GROUP BY ou.org_unit_id, ou.unit_name ORDER BY 信贷客户经理人数 DESC, ou.org_unit_id;	bankreg_main
select i.institution_name, count(*) as 覆盖不足笔数 from provision_snapshot ps join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where ps.provision_stage = 'STAGE_2'   and ps.recognized_amount / ps.required_amount < 0.5 group by i.institution_name order by 覆盖不足笔数 desc, i.institution_name	bankreg_main
select i.institution_name, round(sum(ps.required_amount - ps.recognized_amount), 2) as 拨备缺口合计 from provision_snapshot ps join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where ps.required_amount > ps.recognized_amount group by i.institution_name order by 拨备缺口合计 desc, i.institution_name	bankreg_main
SELECT a.account_id,        a.account_subtype,        ab.ledger_balance FROM account a JOIN account_balance_snapshot ab ON ab.account_id = a.account_id WHERE a.account_kind = 'SAVINGS'   AND a.status = 'DORMANT'   AND NOT EXISTS (     SELECT 1 FROM account_holder h2     WHERE h2.account_id = a.account_id AND h2.holder_role = 'SECONDARY'   ) ORDER BY ab.ledger_balance DESC;	bankreg_main
SELECT pp.party_id, pp.annual_income,        ROUND(SUM(f.limit_amount), 2) AS tot_credit,        ROUND(SUM(f.limit_amount) / pp.annual_income, 2) AS ratio FROM person_profile pp JOIN credit_facility f ON f.obligor_party_id = pp.party_id GROUP BY pp.party_id, pp.annual_income HAVING SUM(f.limit_amount) / pp.annual_income > 3 ORDER BY ratio DESC, pp.party_id LIMIT 10;	bankreg_main
SELECT pp.occupation_code AS occ, pp.employment_sector AS sector, COUNT(*) AS cnt FROM person_profile pp GROUP BY pp.occupation_code, pp.employment_sector ORDER BY cnt DESC, pp.occupation_code, pp.employment_sector;	bankreg_main
SELECT c.status AS card_status, COUNT(*) AS cnt FROM payment_card c JOIN card_type_catalog t ON t.card_type = c.card_type WHERE t.name_zh = '借记卡' GROUP BY c.status ORDER BY cnt DESC, c.status;	bankreg_main
SELECT o.org_unit_id, o.unit_name, COUNT(*) AS n,        ROUND(SUM(e.amount), 2) AS tot FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type JOIN party h ON h.party_id = c.holder_party_id JOIN organization_unit o ON o.org_unit_id = h.home_org_unit_id WHERE t.name_zh = '贷记卡' AND e.is_cash = 1 GROUP BY o.org_unit_id, o.unit_name ORDER BY tot DESC, o.unit_name;	bankreg_main
SELECT e.payment_id, c.card_id, h.party_id, e.business_date, e.amount FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type JOIN party h ON h.party_id = c.holder_party_id WHERE t.name_zh = '贷记卡' AND e.is_cash = 1 ORDER BY e.amount DESC, e.payment_id, c.card_id LIMIT 10;	bankreg_main
SELECT pe.channel,        COUNT(*) AS n,        ROUND(AVG(pe.amount), 2) AS avg_amt FROM payment_event pe WHERE pe.is_cash = 0   AND pe.status = 'SETTLED' GROUP BY pe.channel HAVING AVG(pe.amount) > 11780000 ORDER BY avg_amt DESC, pe.channel;	bankreg_main
SELECT td.account_id, td.maturity_on, a.status FROM term_deposit td JOIN account a ON a.account_id=td.account_id WHERE julianday(td.maturity_on)<julianday('2026-06-30') AND a.status='ACTIVE' ORDER BY td.maturity_on DESC, td.account_id LIMIT 200;	bankreg_main
select a.agreement_id, a.borrower_party_id, a.contract_amount,   round(sum(so.covered_amount), 2) as 担保覆盖合计,   round(a.contract_amount - sum(so.covered_amount), 2) as 保障缺口 from credit_agreement a join secured_obligation so on so.agreement_id = a.agreement_id join security_agreement sa on sa.security_id = so.security_id where a.status = 'ACTIVE' and sa.status = 'ACTIVE' group by a.agreement_id, a.borrower_party_id, a.contract_amount having sum(so.covered_amount) < a.contract_amount order by 保障缺口 desc, a.agreement_id limit 100	bankreg_main
select i.institution_name, g.grade_name_zh, count(*) as 拨备不足借据数 from provision_snapshot ps join risk_classification rc on rc.loan_id = ps.loan_id join classification_grade g on g.grade_code = rc.grade_code join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where g.grade_name_zh = '次级' and ps.required_amount > ps.recognized_amount group by i.institution_name, g.grade_name_zh order by 拨备不足借据数 desc, i.institution_name	bankreg_main
WITH pledged_tot AS (     SELECT collateral_id AS collateral_id, ROUND(SUM(pledged_amount), 2) AS total_pledged,            COUNT(*) AS links     FROM collateral_link     WHERE status = 'ACTIVE'     GROUP BY collateral_id ) SELECT ca.collateral_id AS collateral_id, ca.asset_label AS label,        (SELECT cv.valuation_amount FROM collateral_valuation cv          WHERE cv.collateral_id = ca.collateral_id          ORDER BY cv.valued_on DESC, cv.valuation_id DESC LIMIT 1) AS latest_val,        pt.total_pledged,        ROUND(pt.total_pledged - (SELECT cv.valuation_amount FROM collateral_valuation cv                WHERE cv.collateral_id = ca.collateral_id                ORDER BY cv.valued_on DESC, cv.valuation_id DESC LIMIT 1), 2) AS gap FROM collateral_asset ca JOIN pledged_tot pt ON pt.collateral_id = ca.collateral_id WHERE (SELECT cv.valuation_amount FROM collateral_valuation cv          WHERE cv.collateral_id = ca.collateral_id          ORDER BY cv.valued_on DESC, cv.valuation_id DESC LIMIT 1) < pt.total_pledged ORDER BY gap DESC, ca.collateral_id;	bankreg_main
SELECT gmt.guarantor_party_id, p.display_name,        ROUND((SELECT SUM(a.contract_amount) FROM credit_agreement a               WHERE a.borrower_party_id = gmt.guarantor_party_id), 2) AS own_borrow,        ROUND(SUM(gmt.guaranteed_amount), 2) AS total_guaranteed FROM guarantor_commitment gmt JOIN party p ON p.party_id = gmt.guarantor_party_id WHERE gmt.status = 'ACTIVE'   AND EXISTS (SELECT 1 FROM credit_agreement ca               WHERE ca.borrower_party_id = gmt.guarantor_party_id) GROUP BY gmt.guarantor_party_id, p.display_name HAVING SUM(gmt.guaranteed_amount) > (SELECT SUM(a.contract_amount) FROM credit_agreement a                                      WHERE a.borrower_party_id = gmt.guarantor_party_id) ORDER BY SUM(gmt.guaranteed_amount) DESC, gmt.guarantor_party_id;	bankreg_main
SELECT p.customer_segment,        COUNT(*) AS cnt FROM person_profile pp JOIN party p ON p.party_id = pp.party_id WHERE pp.is_public_official = 1   AND pp.annual_income >= 300000 GROUP BY p.customer_segment ORDER BY cnt DESC, p.customer_segment;	bankreg_main
SELECT i.institution_name, egt.name_zh, COUNT(DISTINCT egm.party_id) AS member_count FROM exposure_group eg JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN institution i ON i.institution_id = eg.institution_id GROUP BY i.institution_name, egt.name_zh HAVING COUNT(DISTINCT egm.party_id) >= 6 ORDER BY COUNT(DISTINCT egm.party_id) DESC, i.institution_name;	bankreg_main
SELECT egm.party_id, p.display_name, COUNT(DISTINCT egm.exposure_group_id) AS group_count FROM exposure_group_member egm JOIN party p ON p.party_id = egm.party_id GROUP BY egm.party_id, p.display_name HAVING COUNT(DISTINCT egm.exposure_group_id) >= 2 ORDER BY COUNT(DISTINCT egm.exposure_group_id) DESC, egm.party_id;	bankreg_main
SELECT p.party_id, p.display_name, rel.rel_count, ag.agreement_count FROM party p JOIN (SELECT source_party_id AS pid, COUNT(*) AS rel_count       FROM party_relation JOIN relation_type_catalog rc ON rc.relation_type = party_relation.relation_type       WHERE rc.relation_name_zh <> '非关联方'       GROUP BY source_party_id) rel ON rel.pid = p.party_id JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count       FROM credit_agreement GROUP BY borrower_party_id) ag ON ag.pid = p.party_id ORDER BY rel.rel_count DESC, p.party_id;	bankreg_main
SELECT pr.relation_id, pr.source_party_id, pr.target_party_id,        CASE WHEN sb.agreement_count IS NULL THEN 0 ELSE sb.agreement_count END AS src_agr,        CASE WHEN tb.agreement_count IS NULL THEN 0 ELSE tb.agreement_count END AS tgt_agr FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type LEFT JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count            FROM credit_agreement GROUP BY borrower_party_id) sb ON sb.pid = pr.source_party_id LEFT JOIN (SELECT borrower_party_id AS pid, COUNT(*) AS agreement_count            FROM credit_agreement GROUP BY borrower_party_id) tb ON tb.pid = pr.target_party_id WHERE rc.relation_name_zh <> '非关联方'   AND sb.agreement_count IS NOT NULL AND tb.agreement_count IS NOT NULL ORDER BY COALESCE(sb.agreement_count, 0) + COALESCE(tb.agreement_count, 0) DESC, pr.relation_id;	bankreg_main
WITH own AS (     SELECT a.borrower_party_id AS party_id, ROUND(SUM(lbs.principal_balance), 2) AS own_loan     FROM credit_agreement a     JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id     JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id     GROUP BY a.borrower_party_id ) SELECT gc.guarantor_party_id AS party_id, p.display_name,        ROUND(SUM(gc.guaranteed_amount), 2) AS guaranteed_total,        COALESCE(o.own_loan, 0) AS own_loan_bal,        ROUND(SUM(gc.guaranteed_amount) - COALESCE(o.own_loan, 0), 2) AS excess FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id LEFT JOIN own o ON o.party_id = gc.guarantor_party_id WHERE gc.status = 'ACTIVE' GROUP BY gc.guarantor_party_id, p.display_name, o.own_loan HAVING SUM(gc.guaranteed_amount) > COALESCE(o.own_loan, 0) ORDER BY excess DESC, gc.guarantor_party_id;	bankreg_main
SELECT sa.security_type, COUNT(DISTINCT sa.security_id) AS sec_count,        ROUND(SUM(so.covered_amount), 2) AS covered_total FROM secured_obligation so JOIN security_agreement sa ON sa.security_id = so.security_id JOIN credit_agreement a ON a.agreement_id = so.agreement_id WHERE a.status = 'ACTIVE' GROUP BY sa.security_type ORDER BY SUM(so.covered_amount) DESC, sa.security_type;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT egm.party_id) AS member_count,        ROUND(SUM(a.contract_amount), 2) AS total_amount FROM exposure_group eg JOIN exposure_group_type_catalog egt ON egt.group_type = eg.group_type JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN institution i ON i.institution_id = eg.institution_id WHERE egt.name_zh = '关联客户群' GROUP BY i.institution_id, i.institution_name HAVING COUNT(DISTINCT egm.party_id) >= 5 ORDER BY SUM(a.contract_amount) DESC, i.institution_name;	bankreg_main
SELECT i.institution_name, f.total_assets, f.total_liabilities, f.net_assets, f.annual_revenue FROM institution i JOIN financial_snapshot f ON f.party_id = 'PTY-'||i.institution_id ORDER BY f.annual_revenue DESC;	bankreg_main
SELECT i.institution_name, ROUND(f.total_liabilities/f.total_assets,4) AS ratio_val FROM institution i JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id ORDER BY ratio_val DESC;	bankreg_main
SELECT i.institution_name, ROUND(c.tier1_capital/c.risk_weighted_assets,4) AS ratio_val FROM capital_snapshot c JOIN institution i ON i.institution_id=c.institution_id ORDER BY ratio_val DESC;	bankreg_main
SELECT i.institution_name, f.annual_revenue, ROUND(f.annual_revenue*100.0/t.agg_rev,2) AS share FROM institution i JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id CROSS JOIN (SELECT SUM(annual_revenue) AS agg_rev FROM financial_snapshot) t WHERE f.annual_revenue*100.0/t.agg_rev > 15 ORDER BY share DESC;	bankreg_main
SELECT i.institution_name, COUNT(*) AS mismatch_cnt FROM managed_asset m JOIN institution i ON i.institution_id=m.originator_institution_id WHERE m.internal_rating<>m.external_rating GROUP BY i.institution_name ORDER BY mismatch_cnt DESC;	bankreg_main
SELECT i.institution_name, COUNT(*) AS high_rate_cnt FROM term_deposit td JOIN account a ON a.account_id=td.account_id JOIN institution i ON i.institution_id=a.institution_id WHERE td.annual_interest_rate>3.0 GROUP BY i.institution_name ORDER BY high_rate_cnt DESC;	bankreg_main
WITH short AS (     SELECT ca.institution_id AS institution_id,            ROUND(SUM(ps.required_amount - ps.recognized_amount), 2) AS shortage     FROM provision_snapshot ps     JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id     JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id     WHERE ps.recognized_amount < ps.required_amount     GROUP BY ca.institution_id ) SELECT s.institution_id AS institution_id,        i.institution_name,        s.shortage AS shortage,        f.net_assets AS net_assets,        ROUND(s.shortage * 100.0 / f.net_assets, 2) AS pct_net_assets FROM short s JOIN institution i ON i.institution_id = s.institution_id JOIN financial_snapshot f ON f.party_id = 'PTY-' || s.institution_id ORDER BY pct_net_assets DESC, s.institution_id;	bankreg_main
WITH prod AS (     SELECT issuer_institution_id AS institution_id,            COUNT(*) AS product_cnt,            ROUND(SUM(actual_raise_amount), 2) AS raised     FROM wealth_product     WHERE status = 'ON_SALE'     GROUP BY issuer_institution_id ) SELECT i.institution_name, pr.product_cnt, pr.raised,        COUNT(*) AS conduct_records,        ROUND(AVG(r.ratio_value), 4) AS avg_ratio FROM product_conduct_event_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN prod pr ON pr.institution_id = i.institution_id WHERE r.exception_flag = 1 GROUP BY i.institution_id, i.institution_name, pr.product_cnt, pr.raised HAVING COUNT(*) >= 2 ORDER BY pr.raised DESC, i.institution_name;	bankreg_main
WITH asset AS (     SELECT originator_institution_id AS institution_id,            COUNT(*) AS asset_cnt,            ROUND(SUM(issued_amount), 2) AS issued     FROM managed_asset     GROUP BY originator_institution_id ), custody AS (     SELECT institution_id,            COUNT(*) AS custody_records,            ROUND(SUM(CASE WHEN exception_flag = 1 THEN amount_value ELSE 0 END), 2) AS except_amount     FROM custody_operation_event_v3     WHERE status_code = 'ACTIVE'     GROUP BY institution_id     HAVING SUM(CASE WHEN exception_flag = 1 THEN 1 ELSE 0 END) >= 2 ) SELECT i.institution_name, a.asset_cnt, a.issued,        c.custody_records, c.except_amount FROM asset a JOIN institution i ON i.institution_id = a.institution_id JOIN custody c ON c.institution_id = i.institution_id ORDER BY a.issued DESC, i.institution_name;	bankreg_main
